// Reads config.json fresh (this workflow has no shared state with the
// main digest run) just to get the Telegram chat ID, then sends an alert
// via the same raw-fetch pattern the main workflow uses.
const fs = require('fs');
const config = JSON.parse(fs.readFileSync('/config/config.json', 'utf8'));

const err = $json;
const workflowName = err.workflow?.name || 'unknown workflow';
const failedNode = err.execution?.lastNodeExecuted || 'unknown node';
const message = err.execution?.error?.message || JSON.stringify(err).slice(0, 300);

const text = [
  `⚠️ ${workflowName} failed`,
  `Node: ${failedNode}`,
  `Error: ${message}`,
  `Time: ${new Date().toISOString()}`
].join('\n');

const token = $env.TELEGRAM_BOT_TOKEN;
const response = await fetch(`https://api.telegram.org/bot${token}/sendMessage`, {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: JSON.stringify({ chat_id: config.telegram.chat_id, text })
});

if (!response.ok) {
  const bodyText = await response.text();
  throw new Error(`Telegram API error ${response.status}: ${bodyText.slice(0, 300)}`);
}

return [{ json: { alert_sent: true, workflow: workflowName, node: failedNode } }];
